const NFC_BLOCO = "\n/* 20/11 (pedido do dono: automatizar o conserto da NF que o ML recusa por endereço) — O CONSERTO NUM CLIQUE, no aviso.\n   O que ele fazia à mão (\"clono a NF, edito... colo campo por campo... clico pra enviar NF... baixo o XML... anexo no\n   MLivre\") são duas rotas do servidor, já provadas com nota de verdade (GOOD, NF 082108 → 082183): criar a nota nova com\n   o endereço da venda e emitir + mandar o XML ao ML. O botão chama as duas, na ordem, e mostra em que pé está.\n   · só o admin vê; pede confirmação (emite nota fiscal);\n   · clicar de novo NÃO cria outra nota: o servidor guarda qual nota nova é de qual nota recusada e continua de onde parou;\n   · a nota recusada não é tocada aqui (cancelar ou devolver é à parte) — o aviso de sucesso lembra disso. */\nconst _nfConserto = {};   /* id da nota recusada → { rodando, texto } — sobrevive ao redesenho do aviso (de 5 em 5 min) */\nfunction botaoConsertoNF(t){\n  const id = String((t && t.nfe_id) || '');\n  if(!souAdmin() || !/^\\d{1,20}$/.test(id)) return '';\n  /* Codex #958: este conserto troca o ENDEREÇO. Nota que o ML recusou por outro motivo (CPF/CNPJ, documento) sairia de\n     novo com o mesmo defeito — sem botão. Quem diz o motivo é o servidor (`conserto`, em lib/nf-travadas). */\n  if(!t || t.conserto !== 'endereco') return '';\n  const st = _nfConserto[id] || {};\n  const num = String((t && t.numero) || id).replace(/[^0-9A-Za-z.\\-\\/ ]/g, '');\n  return '<div style=\"margin-top:6px\"><button class=\"btn sec\" style=\"font-size:12px;padding:6px 10px\" onclick=\"consertarNF(\\'' + id + '\\',\\'' + num + '\\')\">🔧 Consertar: emitir nota nova com o endereço do ML</button>'\n       + ' <span id=\"nfc_' + id + '\" style=\"margin-left:8px\">' + String(st.texto || '').replace(/[&<>\"]/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c])) + '</span></div>';\n}\nfunction _nfcMotivo(r){\n  if(!r) return 'sem resposta do servidor';\n  if(Array.isArray(r.pendencias) && r.pendencias.length) return r.pendencias.join('; ');\n  let m = String(r.erro || r.leia || r.etapa || 'motivo não informado');\n  if(Array.isArray(r.campos) && r.campos.length) m += ' (' + r.campos.map((c) => (c.campo ? c.campo + ': ' : '') + c.motivo).join('; ') + ')';\n  return m;\n}\nasync function consertarNF(id, numero){\n  if(!souAdmin()) return;\n  const st = _nfConserto[id] || (_nfConserto[id] = {});\n  if(st.rodando) return;\n  if(!confirm('Consertar a NF ' + numero + '?\\n\\nO sistema cria no Bling uma nota NOVA igual a esta, com o endereço da venda no Mercado Livre, emite na SEFAZ e manda o XML pro ML.\\n\\nA NF ' + numero + ' (a recusada) NÃO é cancelada nem devolvida aqui.')) return;\n  st.rodando = true;\n  const diz = (t) => { st.texto = t; const e = document.getElementById('nfc_' + id); if(e) e.textContent = t; };\n  const pede = async (rota) => { const r = await fetch('{{PREFIXO}}/' + rota + '?nf=' + encodeURIComponent(id) + '&confirma=sim', {credentials:'same-origin'}); return await r.json().catch(() => null); };\n  try{\n    diz('criando a nota nova no Bling…');\n    const c = await pede('nf-conserto-criar');\n    if(!c || !c.ok){ diz('✗ não criei a nota nova: ' + _nfcMotivo(c)); return; }\n    const nn = String((c.nova && (c.nova.numero || c.nova.id)) || '?');\n    for(let i = 0; i < 8; i++){\n      diz(i ? 'nota nova ' + nn + ': esperando a SEFAZ… (' + i + ')' : 'nota nova ' + nn + (c.ja_existia ? ' já existia' : ' criada') + ' — emitindo e mandando pro ML…');\n      const e = await pede('nf-conserto-enviar');\n      if(e && e.ok && e.etapa === 'no_ml'){\n        diz('✓ nota nova ' + nn + ' autorizada e ACEITA pelo Mercado Livre — a etiqueta aparece no próximo ciclo. A NF ' + numero + ' (recusada) continua no Bling: cancelar ou devolver.');\n        toast('✓ NF ' + nn + ' aceita pelo ML', 6000);\n        checarNFAntigas();   /* 20/11: a nota recusada entra na lista das antigas pendentes */\n        return;\n      }\n      if(!e || !/^aguardando/.test(String(e.etapa || ''))){ diz('✗ nota nova ' + nn + ' criada, mas parou: ' + _nfcMotivo(e)); return; }\n      await new Promise((ok) => setTimeout(ok, NFC_ESPERA_MS));\n    }\n    diz('a SEFAZ ainda não respondeu sobre a nota nova ' + nn + ' — clique em Consertar de novo daqui a pouco (não cria outra nota).');\n  }catch(err){ diz('✗ falha de comunicação — clique em Consertar de novo (não cria outra nota).'); }\n  finally{ st.rodando = false; }\n}\nconst NFC_ESPERA_MS = 20000;\n/* Codex #958: o aviso é desenhado ao abrir o painel, e nessa hora a lista de admins (`/operadores`) pode não ter chegado\n   — o admin via o aviso SEM o botão até a checagem seguinte (5 min). Quando o painel passa a saber quem é admin (login,\n   troca de operador), o aviso é redesenhado. Só quando MUDA — não a cada atualização da lista. */\nlet _nfcAdminVisto = null;\nfunction nfcAoSaberQuemEAdmin(){\n  const a = !!souAdmin();\n  if(a === _nfcAdminVisto) return;\n  const primeira = _nfcAdminVisto === null;\n  _nfcAdminVisto = a;\n  if(!primeira || a) checarNFTravadas();   /* a 1ª vez como não-admin é o que já está na tela */\n  checarNFAntigas();   /* 20/11: e a lista das notas antigas pendentes (só admin vê) */\n}\n\n/* 20/11 — AS NOTAS ANTIGAS QUE O CONSERTO DEIXOU PRA TRÁS. A nota nova já está no ML; a recusada continua autorizada no\n   Bling até alguém cancelar (até 24 h da emissão) ou devolver (depois) — regra do dono. Cancelar e devolver só se fazem\n   na tela do Bling; o que o checkout faz é NÃO DEIXAR ESQUECER: lista (só pro admin) as pendentes e o que cabe a cada uma.\n   A cancelada some sozinha (o servidor vê no Bling); a devolvida, quem devolveu avisa no botão. */\nfunction _nfaLimpo(v){ return String(v == null ? '' : v).replace(/[^0-9A-Za-z.\\-\\/ ]/g, ''); }\nfunction _nfaHoras(h){ return h == null ? '' : (h < 48 ? String(Math.round(h * 10) / 10).replace('.', ',') + ' h' : Math.floor(h / 24) + ' dias'); }\nasync function checarNFAntigas(){\n  const el = document.getElementById('nfAntigas'); if(!el) return;\n  if(!souAdmin()){ el.style.display = 'none'; el.innerHTML = ''; return; }\n  try{\n    const r = await fetch('{{PREFIXO}}/nf-conserto-antigas', {credentials:'same-origin'});\n    const d = await r.json();\n    if(d && d.ok && d.total > 0 && souAdmin()){\n      let h = '<b>🧾 ' + d.total + ' nota' + (d.total>1?'s':'') + ' antiga' + (d.total>1?'s':'') + ' pra cancelar ou devolver</b> — a nota nova já está no Mercado Livre; a recusada continua valendo no Bling até você tratar:';\n      for(const t of d.antigas.slice(0,8)){\n        const id = _nfaLimpo(t.nfe_id), num = _nfaLimpo(t.numero || t.nfe_id);\n        const oque = t.acao === 'cancelar' ? '<b>CANCELAR</b> no Bling (emitida há ' + _nfaHoras(t.horas_desde_a_emissao) + ' — até 24 h ainda cancela)'\n                   : t.acao === 'devolucao' ? 'gerar a <b>NF de DEVOLUÇÃO</b> (emitida há ' + _nfaHoras(t.horas_desde_a_emissao) + ' — passou das 24 h do cancelamento)'\n                   : 'cancelar (até 24 h da emissão) ou devolver — não sei quando foi emitida';\n        h += '<div style=\"margin-top:6px\">• <a href=\"https://www.bling.com.br/notas.fiscais.php#edit/' + id + '\" target=\"_blank\" rel=\"noopener\" style=\"color:#fde68a\"><b>NF ' + num + '</b></a>'\n           + (t.nova_numero ? ' (substituída pela ' + _nfaLimpo(t.nova_numero) + ')' : '') + (t.pedido_ml ? ' · pedido ML ' + _nfaLimpo(t.pedido_ml) : '') + ': ' + oque\n           + '<br>' + (t.acao === 'devolucao' ? '<button class=\"btn\" style=\"font-size:12px;padding:5px 9px;margin-top:4px\" title=\"no computador, com a Toolbox e o Bling aberto: gera e emite a devolução\" onclick=\"gerarDevolucaoNFAntiga(\\'' + id + '\\',\\'' + num + '\\')\">🧾 Gerar devolução (Toolbox)</button> ' : '')\n           + '<button class=\"btn sec\" style=\"font-size:12px;padding:5px 9px;margin-top:4px\" onclick=\"resolverNFAntiga(\\'' + id + '\\',\\'' + num + '\\',\\'devolvida\\')\">✓ já gerei a devolução</button>'\n           + ' <button class=\"btn sec\" style=\"font-size:12px;padding:5px 9px;margin-top:4px\" onclick=\"resolverNFAntiga(\\'' + id + '\\',\\'' + num + '\\',\\'cancelada\\')\">✓ já cancelei</button>'\n           + ' <span style=\"opacity:.75\">(a cancelada some sozinha em até meia hora)</span></div>';\n      }\n      if(d.total > 8) h += '<div style=\"margin-top:6px;opacity:.85\">… e mais ' + (d.total - 8) + '.</div>';\n      el.innerHTML = h; el.style.display = '';\n    } else { el.style.display = 'none'; el.innerHTML = ''; }\n  }catch(e){ /* falhou a consulta: não esconde o que já está na tela */ }\n}\n/* tira da lista (o servidor grava); devolve { ok, erro } */\nasync function _nfaResolverResp(id, como, devId, devNum){\n  try{\n    const r = await fetch('{{PREFIXO}}/nf-conserto-antigas?resolver=' + encodeURIComponent(id) + '&como=' + encodeURIComponent(como) + '&confirma=sim'\n      + (devId ? '&devolucao_id=' + encodeURIComponent(devId) : '') + (devNum ? '&devolucao_numero=' + encodeURIComponent(devNum) : ''), {credentials:'same-origin'});\n    const d = await r.json().catch(() => null);\n    return d && d.ok ? { ok: true } : { ok: false, erro: String((d && d.erro) || 'sem resposta') };\n  }catch(e){ return { ok: false, erro: 'falha de comunicação — tente de novo' }; }\n}\nasync function _nfaResolver(id, como, devId, devNum){ return (await _nfaResolverResp(id, como, devId, devNum)).ok; }\nasync function resolverNFAntiga(id, numero, como){\n  if(!souAdmin()) return;\n  if(!confirm('Tirar a NF ' + numero + ' da lista?\\n\\nSó confirme se ela já foi ' + (como === 'cancelada' ? 'CANCELADA' : 'DEVOLVIDA (NF de devolução emitida)') + ' no Bling. Isto só tira o aviso — não cancela nem devolve nada.')) return;\n  const d = await _nfaResolverResp(id, como);\n  if(d.ok) toast('✓ NF ' + numero + ' fora da lista', 4000); else toast('não consegui tirar da lista: ' + d.erro, 6000);\n  checarNFAntigas();\n}\n/* 21/11 — GERAR A DEVOLUÇÃO PELO BOTÃO (o \"jeito 1\" que o dono escolheu): a TOOLBOX gera e emite a NF de devolução pela\n   tela do Bling — o mesmo caminho do app de Devoluções e do lote da AMB (a ponte GOOD_BRIDGE_CRIAR_DEVOLUCAO, Toolbox\n   2.1.22+, que passou a rodar também nas páginas do checkout). Por isso só funciona NO COMPUTADOR, no navegador da empresa,\n   com a Toolbox e o Bling aberto e logado; a Toolbox RECUSA se o Bling estiver logado em outra empresa e não duplica\n   (devolução que já existe pra nota = \"já existe\"). O servidor confere antes (a nota ainda pendente, passou das 24 h — antes\n   disso a regra é cancelar —, a mesma nota, não cancelada) e dá o id da loja que a tela do Bling exige. Só a devolução\n   AUTORIZADA pela SEFAZ (a Toolbox só responde ok com a situação 2) tira a nota da lista, com o número dela anotado.\n   Codex #970: o \"já existe\" da Toolbox NÃO prova que a devolução foi autorizada — a anti-duplicata do Bling também vale pra\n   um RASCUNHO que a SEFAZ recusou numa tentativa anterior. Então \"já existe\" não tira da lista: manda conferir no Bling. O jeito 2 (pelo servidor, sem computador) está em docs/PLANO-nf-devolucao-servidor.md. */\nconst _nfaGerando = {};\nfunction _nfaPonteViva(){\n  return new Promise(function(ok){\n    let feito = false;\n    function h(ev){ if(ev.source !== window || !ev.data) return; if(ev.data.tipo === 'GOOD_BRIDGE_PONG' || ev.data.tipo === 'GOOD_BRIDGE_INSTALADA'){ if(feito) return; feito = true; window.removeEventListener('message', h); ok(true); } }\n    window.addEventListener('message', h);\n    window.postMessage({ tipo: 'GOOD_BRIDGE_PING' }, '*');\n    setTimeout(function(){ if(feito) return; feito = true; window.removeEventListener('message', h); ok(false); }, 2000);\n  });\n}\nfunction _nfaPedirDevolucao(payload){\n  return new Promise(function(ok){\n    const requisicaoId = 'chk_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);\n    let feito = false;\n    function h(ev){\n      if(ev.source !== window || !ev.data || ev.data.tipo !== 'GOOD_BRIDGE_RESPOSTA' || ev.data.requisicaoId !== requisicaoId || feito) return;\n      feito = true; window.removeEventListener('message', h); clearTimeout(t); ok(ev.data);\n    }\n    window.addEventListener('message', h);\n    window.postMessage({ tipo: 'GOOD_BRIDGE_CRIAR_DEVOLUCAO', requisicaoId: requisicaoId, payload: payload }, '*');\n    /* 110 s: a própria Toolbox desiste em 100 s; a emissão pode demorar. Sem resposta é \"NÃO SEI\" — nunca \"não criou\" */\n    const t = setTimeout(function(){ if(feito) return; feito = true; window.removeEventListener('message', h); ok({ ok: false, codigo: 'TIMEOUT', erro: 'a Toolbox não respondeu em 110 s' }); }, 110000);\n  });\n}\nasync function gerarDevolucaoNFAntiga(id, numero){\n  if(!souAdmin() || _nfaGerando[id]) return;\n  if(!confirm('Gerar e EMITIR a NF de devolução da NF ' + numero + ' no Bling, pela Toolbox?\\n\\nPrecisa: estar no computador, no navegador DESTA empresa, com a Toolbox atualizada e o Bling aberto e logado nesta empresa. Pode levar até 1 minuto.')) return;\n  _nfaGerando[id] = true;\n  try{\n    if(!await _nfaPonteViva()){ toast('⚠️ Toolbox não encontrada nesta página — abra o checkout no COMPUTADOR, no navegador desta empresa, com a Toolbox 2.1.22 ou mais nova (e recarregue a página)', 12000); return; }\n    toast('⏳ conferindo a NF ' + numero + '…', 4000);\n    let prep = null;\n    try{ const r = await fetch('{{PREFIXO}}/nf-conserto-antigas?preparar=' + encodeURIComponent(id), {credentials:'same-origin'}); prep = await r.json().catch(() => null); }catch(e){ prep = null; }\n    if(!prep || !prep.ok){ toast('⚠️ não gerei: ' + String((prep && prep.erro) || 'sem resposta do servidor — tente de novo'), 10000); checarNFAntigas(); return; }\n    toast('⏳ a Toolbox está gerando a devolução da NF ' + numero + ' no Bling — não feche a página…', 110000);\n    const d = await _nfaPedirDevolucao({ idNFOriginal: String(prep.nfe_id), idLoja: prep.id_loja ? String(prep.id_loja) : null, emitir: true, empresa: '{{EMPRESA}}' });\n    const res = (d && d.resultado) || {};\n    const idDev = String((d && d.ok ? res.idNotaDevolucao : d && d.idNotaDevolucao) || ''), numDev = String((d && d.ok ? res.numero : d && d.numero) || '');\n    if(d && d.ok && res.emitida !== false){\n      const ok = await _nfaResolver(id, 'devolvida', idDev, numDev);\n      toast(ok ? '✓ NF de devolução ' + (numDev || '') + ' emitida — a NF ' + numero + ' saiu da lista' : '✓ devolução ' + (numDev || '') + ' emitida, mas não consegui tirar a NF ' + numero + ' da lista — toque em \"já gerei a devolução\"', 9000);\n    } else if(d && d.codigo === 'JA_EXISTE'){\n      toast('⚠️ o Bling já tem uma devolução da NF ' + numero + ' (nada foi criado agora). Confira no Bling: se ela estiver AUTORIZADA, toque em \"já gerei a devolução\"; se for rascunho, emita por lá', 20000);\n    } else if((d && d.codigo === 'RASCUNHO_CRIADO') || (d && d.ok)){\n      toast('⚠️ a NF de devolução ' + (numDev || idDev) + ' foi CRIADA no Bling mas não emitiu — emita ela por lá (não gere de novo) e depois toque em \"já gerei a devolução\". ' + String(d.erro || '').slice(0, 160), 20000);\n    } else if(d && d.codigo === 'TIMEOUT'){\n      toast('⚠️ a Toolbox não respondeu a tempo — a devolução PODE ter sido criada. Confira no Bling; tocar em Gerar de novo é seguro (ela não duplica)', 20000);\n    } else if(d && d.codigo === 'NAO_LOGADO'){\n      toast('⚠️ o Bling não está logado neste navegador — entre no Bling e tente de novo', 12000);\n    } else {\n      toast('⚠️ não gerei a devolução: ' + String((d && d.erro) || 'erro desconhecido').slice(0, 220), 20000);\n    }\n  } finally { delete _nfaGerando[id]; checarNFAntigas(); }\n}\nsetInterval(checarNFAntigas, 5*60000);\n";
/* 20/11: a caixa do aviso das notas antigas pendentes de cancelar/devolver (só admin vê) */
const NFA_DIV = "<div id=\"nfAntigas\" style=\"display:none;margin:8px 12px;padding:10px 14px;border-radius:8px;background:#713f12;color:#fef3c7;font-size:13px;line-height:1.5\"></div>\n";
/* 21/11: no celular, a LISTA rola com a página inteira (o dono: "só rola do busca pra baixo e toda parte de cima estática"),
   e a posição da lista volta ao fechar o pedido */
const ROL_CSS = "    /* 21/11 (o dono, no celular, com o aviso das notas antigas aberto): \"não consigo rolar pra baixo... só rola do busca\n       pra baixo e toda parte de cima estática\". A página tinha a altura exata da tela e só a LISTA rolava, por dentro:\n       a barra de painéis, o cabeçalho e os avisos ficavam parados ocupando quase a tela, e a lista sobrava numa faixa\n       pequena embaixo. Na lista, no celular, a página inteira passa a rolar junto (os avisos sobem e a lista ganha a tela).\n       O pedido aberto (body.peddet) não muda: o cabeçalho some e o topo do pedido continua preso. */\n    body:not(.peddet){height:auto;min-height:100%}\n    body:not(.peddet) .main{flex:0 0 auto}\n    body:not(.peddet) .sidebar{flex:0 0 auto;overflow:visible}\n";
const ROL_ABRE = "  /* 21/11: no celular a página inteira rola na lista — guarda onde a lista estava (só ao ENTRAR no pedido; redesenhar o\n     pedido já aberto não troca a posição guardada), pra voltar no mesmo ponto ao fechar o pedido */\n  if (!document.body.classList.contains('peddet')) _rolagemDaLista = window.scrollY || 0;\n";
const ROL_FECHA_NOVO = "let _rolagemDaLista = 0;\nfunction mostrarPlaceholder(){\n  const estavaNoPedido = document.body.classList.contains('peddet');\n  document.body.classList.remove('peddet'); $('detail').innerHTML='<div class=\"placeholder\">← selecione um pedido à esquerda</div>';\n  if (estavaNoPedido) window.scrollTo(0, _rolagemDaLista);   /* volta pro ponto da lista em que o pedido foi aberto */\n}\n";
const ROL_FECHA_VELHO = "function mostrarPlaceholder(){ document.body.classList.remove('peddet'); $('detail').innerHTML='<div class=\"placeholder\">← selecione um pedido à esquerda</div>'; }\n";
/* 23/11: "Atualizar" e "Bling agora" esperam a consulta ao Bling que começou depois do clique */
/* 26/11: o texto do card quebra em vez de alargar a coluna (pedido do dono) */
const SMETA_NOVO = "  /* 26/11 (o dono: \"faz caber ali as informações no card, pra não ter q puxar essa barrinha pra horizontal\"): o motivo do\n     \"sem etiqueta\" às vezes traz um texto comprido SEM espaço (a resposta crua de um serviço) — ele não quebrava e alargava\n     a coluna inteira dos cards. Agora quebra onde precisar. */\n  .smeta{font-size:13px;color:var(--mut);font-family:ui-monospace,monospace;margin-top:4px;overflow-wrap:anywhere;word-break:break-word;min-width:0}\n";
const SMETA_VELHO = "  .smeta{font-size:13px;color:var(--mut);font-family:ui-monospace,monospace;margin-top:4px}\n";
const ATU_NOVO_0 = "  toast('🔄 Consultando o Bling agora… (~30-60s, a lista atualiza sozinha)');\n  let r = null;\n";
const ATU_VELHO_0 = "  toast('🔄 Consultando o Bling agora… (~30-60s, a lista atualiza sozinha)');\n";
const ATU_NOVO_1 = "  try{\n    /* Codex #971: o pedido também tem prazo (20 s) — servidor mudo não deixa o botão travado */\n    const acB = (typeof AbortController === 'function') ? new AbortController() : null;\n    const tmB = acB ? setTimeout(() => acB.abort(), 20000) : null;\n    try{ r = await api('{{PREFIXO}}/ciclo-agora', {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}', signal: acB ? acB.signal : undefined}); }\n    finally{ if(tmB) clearTimeout(tmB); }\n";
const ATU_VELHO_1 = "  try{\n    const r = await postJson('{{PREFIXO}}/ciclo-agora', {});\n";
const ATU_NOVO_2 = "  }catch(e){ toast('falha: '+e.message); if(b) b.disabled=false; return; }\n  /* 23/11: espera a consulta que COMEÇOU depois do clique terminar (antes: 45 s fixos — às vezes cedo demais) */\n  const pronto = await _esperarCicloDepois(r.pedido_em, 180000);\n  await carregarLista();\n  toast(pronto ? '✓ lista atualizada com o Bling' : '⏳ o Bling está demorando — a lista atualiza sozinha quando a consulta terminar', pronto ? 3000 : 8000);\n  if(b) b.disabled=false;\n}\n/* 23/11 — o dono: \"é meio lerdo o checkout. eu clico em atualizar tb, e nem sempre reflete o bling\". O painel recarregava a\n   lista 4 e 8 s depois do clique, antes de a consulta ao Bling terminar (e, com uma consulta já rodando, o clique era\n   descartado). Agora espera, olhando a /lista de 5 em 5 s, uma consulta que tenha COMEÇADO depois do pedido (a hora vem do\n   relógio do servidor) — a que já rodava tirou a foto do ATENDIDO antes do clique e não traz o pedido novo. Devolve true\n   quando ela terminou; false se passou do teto (a lista se atualiza sozinha depois) ou se não há hora do pedido. */\nasync function _esperarCicloDepois(pedidoEm, tetoMs){\n  const alvo = Date.parse(pedidoEm || '');\n  if(!isFinite(alvo)) return false;\n  const fim = Date.now() + (Number(tetoMs) || 180000);\n  while(Date.now() < fim){\n    await new Promise(ok => setTimeout(ok, 5000));\n    /* Codex #971: cada consulta à lista tem prazo (o que falta da espera, no máximo 15 s) — uma que pendure não pode segurar\n       o botão travado além do teto */\n    const resta = fim - Date.now();\n    if(resta <= 0) break;\n    let d = null;\n    const ac = (typeof AbortController === 'function') ? new AbortController() : null;\n    const tm = ac ? setTimeout(() => ac.abort(), Math.min(15000, resta)) : null;\n    try{ d = await api('{{PREFIXO}}/lista', ac ? { signal: ac.signal } : undefined); }catch(e){ d = null; }\n    finally{ if(tm) clearTimeout(tm); }\n    const c = d ? Date.parse(d.ciclo_comecou_em || '') : NaN;\n    if(isFinite(c) && c >= alvo) return true;\n  }\n  return false;\n";
const ATU_VELHO_2 = "  }catch(e){ toast('falha: '+e.message); if(b) b.disabled=false; return; }\n  setTimeout(()=>{ carregarLista(); toast('✓ lista atualizada com o Bling'); if(b) b.disabled=false; }, 45000);\n";
const ATU_NOVO_3 = "  const orig = b ? b.textContent : '';\n  if(b){ b.textContent='⏳ Consultando o Bling…'; b.disabled = true; }\n";
const ATU_VELHO_3 = "  const orig = b ? b.textContent : '';\n  if(b){ b.textContent='⏳ Sincronizando…'; b.disabled = true; }\n";
const ATU_NOVO_4 = "  try{\n    /* o pedido também tem prazo (20 s): servidor que não responde não deixa o botão travado */\n    const acR = (typeof AbortController === 'function') ? new AbortController() : null;\n    const tmR = acR ? setTimeout(() => acR.abort(), 20000) : null;\n    const r = await fetch('{{PREFIXO}}/atualizar', Object.assign({ method:'POST' }, acR ? { signal: acR.signal } : {})).then(x => x.json()).catch(() => null);\n    if(tmR) clearTimeout(tmR);\n    if(!r || !r.pedido_em){ await carregarLista(); toast('Falha ao pedir a atualização ao servidor — tente de novo', 6000); return; }\n    await carregarLista();   /* o que já está pronto aparece na hora; a consulta nova chega em seguida */\n    const pronto = await _esperarCicloDepois(r.pedido_em, 180000);\n    await carregarLista();\n    toast(pronto ? 'Sincronizado com o Bling' : '⏳ o Bling está demorando — a lista atualiza sozinha quando a consulta terminar', pronto ? 3000 : 8000);\n";
const ATU_VELHO_4 = "  try{\n    await fetch('{{PREFIXO}}/run', { method:'POST' });\n    await new Promise(r=>setTimeout(r, 4000)); await carregarLista();\n    await new Promise(r=>setTimeout(r, 4000)); await carregarLista();\n    toast('Sincronizado com o Bling');\n";
/* 23/11 (Codex #971): a recarga da lista tem prazo (20 s) e prazo estourado com a lista na tela não a apaga */
const CL_NOVO_A = "    /* Codex #971: a consulta tem prazo (20 s) — uma /lista que pendure não pode travar quem a espera (Atualizar / Bling agora) */\n    const acL = (typeof AbortController === 'function') ? new AbortController() : null;\n    const tmL = acL ? setTimeout(() => acL.abort(), 20000) : null;\n    let d;\n    try{ d = await api('{{PREFIXO}}/lista', acL ? { signal: acL.signal } : undefined); }\n    finally{ if(tmL) clearTimeout(tmL); }\n";
const CL_VELHO_A = "    const d = await api('{{PREFIXO}}/lista');\n";
const CL_NOVO_B = "  }catch(e){\n    /* prazo estourado com a lista já na tela: mantém o que está aí (o recarregamento de 20 s tenta de novo) */\n    if(e && e.name==='AbortError' && listaCache && listaCache.length) return;\n    $('listaPedidos').innerHTML='<div class=\"empty\">erro: '+esc(e.message)+'</div>';\n  }\n";
const CL_VELHO_B = "  }catch(e){ $('listaPedidos').innerHTML='<div class=\"empty\">erro: '+esc(e.message)+'</div>'; }\n";
const atu = (t, prefixo) => t.split('{{PREFIXO}}').join(prefixo);   /* as trocas do "Atualizar" levam o prefixo da empresa */
