const nfcBloco = (prefixo, empresa) => NFC_BLOCO.split('{{PREFIXO}}').join(prefixo).split('{{EMPRESA}}').join(empresa);   /* 21/11: o bloco passou a usar a empresa (a Toolbox precisa saber de qual é) */
const SIT_NOVO = "    /* 12/11 (pedido do dono): a lista ganhou um segundo tipo -- nota parada em \"Consultar situacao\" que a consulta\n       automatica nao destravou. Cada tipo com o SEU titulo (o do Mercado Livre nao vale pra ela). O texto vem escapado:\n       o motivo pode trazer a resposta da SEFAZ. */\n    const _e = (t) => String(t == null ? '' : t).replace(/[&<>\"]/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n    const doML = d.travadas.filter((t) => !t.tipo), daSit = d.travadas.filter((t) => t.tipo === 'consultar_situacao');\n    let h = '';\n    if(doML.length){\n      h += '<b>\\u26a0\\ufe0f ' + doML.length + ' nota' + (doML.length>1?'s':'') + ' fiscal' + (doML.length>1?'is':'') + ' travada' + (doML.length>1?'s':'') + ' \\u2014 o Mercado Livre recusou e a rotina parou de tentar.</b><br>';\n      for(const t of doML.slice(0,6)){\n        h += '<div style=\"margin-top:6px\">\\u2022 <b>NF ' + (t.numero||t.nfe_id) + '</b>'\n           + (t.pedido_ml ? ' \\u00b7 pedido ML ' + t.pedido_ml : '')\n           + '<br><span style=\"opacity:.85\">' + t.motivo + ' \\u2014 ' + t.como_resolver + '</span></div>';\n      }\n      if(doML.length>6) h += '<div style=\"margin-top:6px;opacity:.8\">\\u2026 e mais ' + (doML.length-6) + '</div>';\n    }\n    if(daSit.length){\n      if(h) h += '<div style=\"margin-top:10px\"></div>';\n      h += '<b>\\u26a0\\ufe0f ' + daSit.length + ' nota' + (daSit.length>1?'s':'') + ' parada' + (daSit.length>1?'s':'') + ' em \\u201cConsultar situa\\u00e7\\u00e3o\\u201d no Bling \\u2014 o pedido n\\u00e3o anda enquanto ela n\\u00e3o for consultada.</b><br>';\n      for(const t of daSit.slice(0,6)){\n        h += '<div style=\"margin-top:6px\">\\u2022 <b>NF ' + _e(t.numero||t.nfe_id) + '</b>'\n           + (t.detalhe ? ' \\u00b7 ' + _e(t.detalhe) : '')\n           + '<br><span style=\"opacity:.85\">' + _e(t.motivo) + ' \\u2014 ' + _e(t.como_resolver) + '</span></div>';\n      }\n      if(daSit.length>6) h += '<div style=\"margin-top:6px;opacity:.8\">\\u2026 e mais ' + (daSit.length-6) + '</div>';\n    }\n    if(!h){ el.style.display='none'; return; }\n";
const SIT_VELHO = "    let h = '<b>\\u26a0\\ufe0f ' + d.total + ' nota' + (d.total>1?'s':'') + ' fiscal' + (d.total>1?'is':'') + ' travada' + (d.total>1?'s':'') + ' \\u2014 o Mercado Livre recusou e a rotina parou de tentar.</b><br>';\n    for(const t of d.travadas.slice(0,6)){\n      h += '<div style=\"margin-top:6px\">\\u2022 <b>NF ' + (t.numero||t.nfe_id) + '</b>'\n         + (t.pedido_ml ? ' \\u00b7 pedido ML ' + t.pedido_ml : '')\n         + '<br><span style=\"opacity:.85\">' + t.motivo + ' \\u2014 ' + t.como_resolver + '</span></div>';\n    }\n    if(d.total>6) h += '<div style=\"margin-top:6px;opacity:.8\">\\u2026 e mais ' + (d.total-6) + '</div>';\n";
assert.strictEqual(html.replace(NFC_LINHA, '').split(SIT_NOVO).length, 2, 'o aviso de NF em dois blocos não está no painel (uma vez)');
