const FIN_NOVO = "    /* 15/11 (Codex #896): o servidor passou a recusar a finalização que NÃO conseguiu gravar (503 nao_gravado) — e qualquer\n       ok:false que não seja \"já finalizado\" é falha: avisa, NÃO fecha, NÃO solta a reserva, o pedido fica na tela pra tentar de novo */\n    if(!r || (r.ok===false && !r.ja_finalizado)){ toast('✗ '+pedidoAtual.numero+' NÃO finalizado: '+((r&&r.erro)||'o servidor não respondeu')+(r&&r.nao_gravado?' — nada foi feito, tente de novo':''), 8000); return; }\n";
const TOAST_NOVO = "function toast(m, ms){ const t=$('toast'); t.textContent=m; t.classList.add('show'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('show'), ms||1800); }   /* 15/11: duração opcional — aviso de falha fica mais tempo */";
const TOAST_VELHO = "function toast(m){ const t=$('toast'); t.textContent=m; t.classList.add('show'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('show'),1800); }";
