/* 15/11 (auditoria do Codex, P2 nº 2): a assinatura do QZ — o painel guarda o pedido pelo resumo que o qz-tray pede pra assinar
   e manda os dois ao servidor por POST (o servidor só assina pedido de impressão de quem está logado). Mudança de propósito;
   pro byte a byte, volta ao GET de antes. */
const QZ_HASH_NOVO = "  // 15/11 (Codex P2-2): o qz-tray pede pra assinar o RESUMO (sha256) de {call, params, timestamp} — o servidor só assina se\n  // vir TAMBÉM o pedido que gerou o resumo (e ele for imprimir/olhar impressora). O hash passa por aqui: guardo o pedido\n  // pelo resumo pra mandar os dois no /qz-sign. Sem a lib sha256 (CDN fora), o SubtleCrypto do navegador faz o mesmo hash.\n  const _qzPedidos = new Map();\n  const _qzHex = (buf) => Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2,'0')).join('');\n  const _qzSha = (d) => window.sha256 ? Promise.resolve(sha256(d)) : crypto.subtle.digest('SHA-256', new TextEncoder().encode(d)).then(_qzHex);\n  qz.api.setSha256Type(d => _qzSha(d).then(h => { if(_qzPedidos.size > 50) _qzPedidos.clear(); _qzPedidos.set(h, d); return h; }));\n", QZ_HASH_VELHO = "  if(window.sha256) qz.api.setSha256Type(d => sha256(d));\n";
const qzFetchNovo = (pref) => "          const pedido = _qzPedidos.get(toSign) || null; _qzPedidos.delete(toSign);\n          fetch('" + pref + "/qz-sign', {method:'POST', cache:'no-store', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ request: toSign, pedido })})\n            .then(function(r){ if(!r.ok) return r.json().then(function(j){ throw new Error((j&&j.erro)||('HTTP '+r.status)); }); return r.text(); }).then(resolve).catch(reject);\n";
const qzFetchVelho = (pref) => "          fetch('" + pref + "/qz-sign?request='+encodeURIComponent(toSign), {cache:'no-store'})\n            .then(function(r){ return r.text(); }).then(resolve).catch(reject);\n";
const QZ_FETCH_NOVO = qzFetchNovo(marca.PREFIXO), QZ_FETCH_VELHO = qzFetchVelho(marca.PREFIXO);
for (const [n, oq] of [[QZ_HASH_NOVO, 'o hash do QZ que guarda o pedido'], [QZ_FETCH_NOVO, 'o POST do /qz-sign com resumo e pedido']]) assert.strictEqual(html.split(n).length, 2, oq + ' não está no painel (uma vez)');
assert.ok(!html.includes('/qz-sign?request='), 'o painel ainda chama o GET /qz-sign?request= (o servidor responde 405)');

