assert.strictEqual(crypto.createHash('sha256').update(html.replace(SMETA_NOVO, SMETA_VELHO).replace(FIN_NOVO, '').replace(TOAST_NOVO, TOAST_VELHO).replace(QZ_HASH_NOVO, QZ_HASH_VELHO).replace(QZ_FETCH_NOVO, QZ_FETCH_VELHO).replace(NFC_LINHA, '').replace(NFC_LINHA2, '').replace(NFA_DIV, '').replace(atu(ATU_NOVO_0, marca.PREFIXO), atu(ATU_VELHO_0, marca.PREFIXO)).replace(atu(ATU_NOVO_1, marca.PREFIXO), atu(ATU_VELHO_1, marca.PREFIXO)).replace(atu(ATU_NOVO_2, marca.PREFIXO), atu(ATU_VELHO_2, marca.PREFIXO)).replace(atu(ATU_NOVO_3, marca.PREFIXO), atu(ATU_VELHO_3, marca.PREFIXO)).replace(atu(ATU_NOVO_4, marca.PREFIXO), atu(ATU_VELHO_4, marca.PREFIXO)).replace(atu(CL_NOVO_A, marca.PREFIXO), atu(CL_VELHO_A, marca.PREFIXO)).replace(CL_NOVO_B, CL_VELHO_B).replace(ROL_CSS, '').replace(ROL_ABRE, '').replace(ROL_FECHA_NOVO, ROL_FECHA_VELHO).replace(nfcBloco(marca.PREFIXO, marca.EMPRESA), '').replace(SIT_NOVO, SIT_VELHO).replace(AVISO_ABRIR, '').replace(CEL_CSS, '').replace(ADM_NOVO, ADM_VELHO).replace(BARRA_NOVO, BARRA_VELHO).replace(NAVV_NOVO, NAVV_VELHO).replace(B3, '').replace(NF_HIST, "' '+linksMkt(h)").replace(REABRIR_POST, ');').replace(CARD_PICK_NOVO, CARD_PICK_VELHO).replace(QTD_JS, '').replace(QTD_CSS, '').replace(LAYOUT_CSS, ''), 'utf8').digest('hex'), SHA_GIRASSOL_ANTES, 'o painel da Girassol pela peça mudou além das mudanças de propósito (byte a byte)');
